package com.quizmaster.servlet;
import com.quizmaster.dao.*;import com.quizmaster.model.*;import com.quizmaster.util.*;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.sql.*;
@WebServlet(urlPatterns={"/admin/dashboard","/admin/quizzes","/admin/questions","/admin/results","/admin/export"})public class AdminServlet extends HttpServlet{
 private final QuizDAO quizzes=new QuizDAO();private final QuestionDAO questions=new QuestionDAO();private final AttemptDAO attempts=new AttemptDAO();
 protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{try{String action=r.getServletPath();if(action.equals("/admin/dashboard")||action.equals("/admin/quizzes")){r.setAttribute("quizzes",quizzes.all());r.getRequestDispatcher("/WEB-INF/views/admin/quizzes.jsp").forward(r,p);}else if(action.equals("/admin/questions")){long id=WebUtil.positive(r.getParameter("quiz"));Quiz q=quizzes.get(id);if(q==null){p.sendError(404);return;}r.setAttribute("quiz",q);r.setAttribute("questions",questions.list(id,false));r.getRequestDispatcher("/WEB-INF/views/admin/questions.jsp").forward(r,p);}else if(action.equals("/admin/results")||action.equals("/admin/export")){long id=WebUtil.positive(r.getParameter("quiz"));if(id<0){p.sendError(400);return;}var rows=attempts.history(null,id);if(action.endsWith("export")){p.setContentType("text/csv;charset=UTF-8");p.setHeader("Content-Disposition","attachment; filename=results.csv");PrintWriter out=p.getWriter();out.println("Student,Quiz,Score,Total,Status,Started");for(var row:rows){out.println(csv(row.student())+","+csv(row.quiz())+","+row.score()+","+row.maxScore()+","+csv(row.status())+","+csv(row.date().toString()));}}else{r.setAttribute("results",rows);r.getRequestDispatcher("/WEB-INF/views/admin/results.jsp").forward(r,p);}}}catch(SQLException e){getServletContext().log("Admin read error",e);p.sendError(500,"Database error");}}
 private String csv(String s){return "\""+s.replace("\"","\"\"").replace("\r"," ").replace("\n"," ").replaceFirst("^[=+@-]","'")+"\"";}
 protected void doPost(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{r.setCharacterEncoding("UTF-8");if(!WebUtil.valid(r)){p.sendError(403);return;}String action=r.getServletPath();try{if(action.equals("/admin/quizzes")){long id=WebUtil.positive(r.getParameter("id"));if("delete".equals(r.getParameter("op"))){quizzes.delete(id);}else{String title=WebUtil.clean(r.getParameter("title"));int mins=WebUtil.number(r.getParameter("duration"),1,240),marks=WebUtil.number(r.getParameter("marks"),1,10000);if(title.isEmpty()||title.length()>200||mins<0||marks<0){p.sendError(400);return;}User u=(User)r.getSession().getAttribute("user");quizzes.save(id,title,mins,marks,u.getId());}p.sendRedirect(r.getContextPath()+"/admin/quizzes");}else if(action.equals("/admin/questions")){long quiz=WebUtil.positive(r.getParameter("quiz")),id=WebUtil.positive(r.getParameter("id"));if(quizzes.get(quiz)==null){p.sendError(404);return;}if("delete".equals(r.getParameter("op"))){questions.delete(id,quiz);}else{String text=WebUtil.clean(r.getParameter("text")),a=WebUtil.clean(r.getParameter("a")),b=WebUtil.clean(r.getParameter("b")),c=WebUtil.clean(r.getParameter("c")),d=WebUtil.clean(r.getParameter("d")),correct=WebUtil.clean(r.getParameter("correct"));int marks=WebUtil.number(r.getParameter("marks"),1,1000);if(text.isEmpty()||text.length()>2000||a.isEmpty()||b.isEmpty()||c.isEmpty()||d.isEmpty()||a.length()>500||b.length()>500||c.length()>500||d.length()>500||!correct.matches("[ABCD]")||marks<0){p.sendError(400);return;}questions.save(id,quiz,text,a,b,c,d,correct,marks);}p.sendRedirect(r.getContextPath()+"/admin/questions?quiz="+quiz);}else p.sendError(405);}catch(SQLException e){getServletContext().log("Admin write failed",e);p.sendError(409,"Cannot change records referenced by attempts or invalid data");}}
}
